from pathlib import Path
from html import escape
ROOT=Path(__file__).parent

def btn(text,url,style='gold'):
 return f'<a class="btn {style}" href="{escape(url)}">{escape(text)} <span class="arrow" aria-hidden="true">→</span></a>'
def head(title,description,page):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0e2933"><meta name="description" content="{escape(description,quote=True)}"><title>{escape(title)} | EvoSys Pro Wholesale</title><link rel="stylesheet" href="assets/site.css"><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><script src="assets/site.js" defer></script></head><body data-page="{page}"><a href="#main" style="position:absolute;left:-9999px;top:0;background:white;color:black;padding:12px;z-index:999" onfocus="this.style.left='10px'" onblur="this.style.left='-9999px'">Skip to content</a><div id="site-nav"></div><main id="main">'''
def end():return '</main><div id="site-footer"></div></body></html>'
def pagehero(kicker,title,text,cta='',compact=True):
 return f'''<section class="page-hero {'compact' if compact else ''}"><div class="container"><span class="small-eyebrow on-dark">{kicker}</span><h1>{title}</h1><p>{text}</p>{f'<div class="hero-actions">{cta}</div>' if cta else ''}</div></section>'''
def faq(entries):
 return f'''<section class="section"><div class="container faq-layout"><div><span class="small-eyebrow">Good to know</span><h2 class="section-title">Straight answers.<br>Clear next steps.</h2><p class="section-text">Questions should be easy to ask. Our process is built around transparency, not pressure.</p></div><div class="faq-list">{''.join(f'<details class="faq-item"><summary>{q}</summary><p>{a}</p></details>' for q,a in entries)}</div></div></section>'''
def benefits(items):
 return '<div class="benefit-grid">'+''.join(f'<article class="benefit-card"><span class="symbol">{i}</span><h3>{h}</h3><p>{p}</p></article>' for i,h,p in items)+'</div>'
def section_head(eyebrow,title,text,center=False):
 return f'<div class="section-head {"center" if center else ""}"><span class="small-eyebrow">{eyebrow}</span><h2 class="section-title">{title}</h2><p class="section-text">{text}</p></div>'

